package id.duakelinci.dashboard;
import static id.duakelinci.dashboard.ApiModels.*;import java.io.*;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;
@Service class ImportService{
 final SalesCsvParser parser;final CsvSalesRepository repo;final Path tempDir;final long maxBytes;final Duration ttl;final ConcurrentMap<String,Entry> previews=new ConcurrentHashMap<>();final List<ImportAudit> audits=new CopyOnWriteArrayList<>();
 ImportService(SalesCsvParser p,CsvSalesRepository r,@Value("${sales.import.dir:../runtime/sales-imports}")String dir,@Value("${sales.import.max-bytes:10485760}")long max,@Value("${sales.import.preview-minutes:30}")long mins){parser=p;repo=r;tempDir=Path.of(dir).toAbsolutePath().normalize().resolve("previews");maxBytes=max;ttl=Duration.ofMinutes(mins);}
 ImportPreview preview(MultipartFile file)throws IOException{cleanup();String name=safe(file.getOriginalFilename());if(file.isEmpty())throw new ImportException(400,"EMPTY_FILE","File CSV kosong");if(file.getSize()>maxBytes)throw new ImportException(413,"FILE_TOO_LARGE","Ukuran file melebihi 10 MB");if(!name.toLowerCase(Locale.ROOT).endsWith(".csv"))throw new ImportException(400,"INVALID_FILE_TYPE","Pilih file dengan ekstensi .csv");String ct=file.getContentType();if(ct!=null&&!Set.of("text/csv","application/csv","application/vnd.ms-excel","text/plain","application/octet-stream").contains(ct))throw new ImportException(400,"INVALID_CONTENT_TYPE","Content-Type file tidak didukung");Files.createDirectories(tempDir);Path raw=Files.createTempFile(tempDir,"upload-",".csv"),valid=null;try{try(var in=file.getInputStream()){Files.copy(in,raw,StandardCopyOption.REPLACE_EXISTING);}var result=parser.parse(raw);if(result.structural())throw new ImportException(400,"STRUCTURAL_ERROR","File tidak dapat diaktifkan",result.errors());if(result.records().isEmpty())throw new ImportException(422,"NO_VALID_ROWS","File tidak memiliki baris valid",result.errors());valid=Files.createTempFile(tempDir,"preview-",".csv");Files.deleteIfExists(valid);parser.writeValidated(valid,result.records());String token=UUID.randomUUID().toString();Instant now=Instant.now();var entry=new Entry(token,name,file.getSize(),result.checksum(),now,now.plus(ttl),valid,result);previews.put(token,entry);valid=null;var dto=dto(entry);audit(entry,"PREVIEW_READY",null);return dto;}finally{Files.deleteIfExists(raw);if(valid!=null)Files.deleteIfExists(valid);}}
 Metadata activate(ActivateImportRequest req)throws IOException{cleanup();var e=previews.get(req.previewId());if(e==null)throw new ImportException(410,"PREVIEW_EXPIRED","Pratinjau kedaluwarsa atau tidak tersedia");synchronized(e){if(e.used)throw new ImportException(409,"PREVIEW_USED","Pratinjau sudah pernah digunakan");if(Instant.now().isAfter(e.expires)){expire(e);throw new ImportException(410,"PREVIEW_EXPIRED","Pratinjau telah kedaluwarsa");}if(!e.checksum.equals(req.expectedChecksum()))throw new ImportException(409,"CHECKSUM_MISMATCH","Checksum pratinjau tidak cocok");int rejected=(int)e.result.errors().stream().filter(ValidationError::rejected).count();if(rejected>0&&!req.acceptRejectedRows())throw new ImportException(400,"REJECTED_ROWS_NOT_ACCEPTED","Konfirmasi pengeluaran baris yang ditolak diperlukan");var m=repo.activate(e.validated,e.name,rejected,e.created,e.checksum);e.used=true;previews.remove(e.token);Files.deleteIfExists(e.validated);audit(e,"ACTIVATED",null);return m;}}
 void cancel(String id){var e=previews.remove(id);if(e!=null)try{Files.deleteIfExists(e.validated);}catch(IOException ignored){}}List<ImportAudit> history(int page,int size){int from=Math.min(Math.max(0,page)*Math.min(100,Math.max(1,size)),audits.size());int to=Math.min(audits.size(),from+Math.min(100,Math.max(1,size)));return new ArrayList<>(audits).reversed().subList(from,to);}
 void cleanup(){for(var e:previews.values())if(Instant.now().isAfter(e.expires))expire(e);}void expire(Entry e){previews.remove(e.token);try{Files.deleteIfExists(e.validated);}catch(IOException ignored){}audit(e,"EXPIRED",null);}
 ImportPreview dto(Entry e){var r=e.result;var errs=r.errors().stream().limit(100).toList();long net=0;for(var x:r.records())try{net=Math.addExact(net,x.netSalesIdr());}catch(ArithmeticException ex){throw new ImportException(422,"AGGREGATE_OVERFLOW","Total net sales melampaui batas");}return new ImportPreview(e.token,e.name,e.size,e.checksum,e.created,e.expires,"READY",r.totalRows(),r.records().size(),(int)r.errors().stream().filter(ValidationError::rejected).count(),Math.max(0,r.errors().size()-100),r.records().stream().map(SalesRecord::date).min(Comparator.naturalOrder()).orElse(null),r.records().stream().map(SalesRecord::date).max(Comparator.naturalOrder()).orElse(null),(int)r.records().stream().map(SalesRecord::invoiceNo).distinct().count(),(int)r.records().stream().map(SalesRecord::outletId).distinct().count(),(int)r.records().stream().map(SalesRecord::region).distinct().count(),(int)r.records().stream().map(SalesRecord::brand).distinct().count(),net,r.structural(),errs);}
 void audit(Entry e,String result,String code){audits.add(new ImportAudit(UUID.randomUUID(),Instant.now(),e.name,e.size,e.checksum,e.result.records().size(),(int)e.result.errors().stream().filter(ValidationError::rejected).count(),result,code,UUID.randomUUID().toString()));}static String safe(String n){if(n==null||n.isBlank())return"dataset.csv";String s=Path.of(n.replace('\\','/')).getFileName().toString().replaceAll("[\\p{Cntrl}]","_");return s.length()>180?s.substring(s.length()-180):s;}
 static class ImportException extends RuntimeException{final int status;final String code;final List<ValidationError> errors;ImportException(int s,String c,String m){this(s,c,m,List.of());}ImportException(int s,String c,String m,List<ValidationError> e){super(m);status=s;code=c;errors=e.stream().limit(100).toList();}}
 static class Entry{final String token,name,checksum;final long size;final Instant created,expires;final Path validated;final SalesCsvParser.ParseResult result;boolean used;Entry(String t,String n,long s,String c,Instant cr,Instant ex,Path p,SalesCsvParser.ParseResult r){token=t;name=n;size=s;checksum=c;created=cr;expires=ex;validated=p;result=r;}}
}
